head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF05245.xml";
scwin.gIsurCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_getSkillGrwComGrace = function() {
    trs_Read.Action = "/SkillGrwComGrace.do?method=getSkillGrwComGrace" + "&ISUR_CD=" + scwin.gIsurCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_ContentsInfo)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    //var operLossYn = getObjectValue(cmb_OPERLOSS_GRACE_YN);

    var rtn = confirm('저장 하시겠습니까?');
    if (rtn == 1) {
        dts_ContentsInfo.setCellData(1, "EMP_NO", js_emp_no);
        trs_Save.Action = "/SkillGrwComGrace.do?method=insertSkillGrwComGrace" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_ContentsInfo)";
        trs_Save.Post();
    }
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    top_list_sync = $c.frame.path("../").fn_list_sync;
    top_list_sync();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.dts_ContentsInfo_OnLoadError = function() {
    $c.win.alert('dts_ContentsInfo.OnLoadError()');
};
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {

};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    getParaIsurCd = $c.frame.path("../").fn_getParaIsurCd;
    scwin.gIsurCd = getParaIsurCd();
    scwin.fn_getSkillGrwComGrace();
};
